import math

raw=[]; y=[]
with open('graphene.dat') as f:
    for line in f:
        line=line.strip()
        if not line: continue
        a,b=line.split()
        raw.append(float(a.replace(',','.')))
        y.append(float(b.replace(',','.')))
data=sorted((1e7/v, yy) for v,yy in zip(raw,y))
xs=[a for a,b in data]; ys=[b for a,b in data]

def profile(x,x0,gamma,kind):
    if kind=='lor':
        return gamma*gamma/((x-x0)**2+gamma*gamma)
    return math.exp(-0.5*((x-x0)/gamma)**2)  # gamma = sigma for gaussian

def linear_peak_fit(x,y,x0,gamma,kind):
    f=[profile(xi,x0,gamma,kind) for xi in x]
    n=len(x); sf=sum(f); sy=sum(y); sff=sum(v*v for v in f); sfy=sum(fi*yi for fi,yi in zip(f,y))
    det=n*sff-sf*sf
    A=(n*sfy-sf*sy)/det
    c=(sy-A*sf)/n
    sse=sum((yi-c-A*fi)**2 for xi,fi,yi in zip(x,f,y))
    return A,c,sse

def fit_peak(x,y,kind,center,window):
    xw=[xi for xi in x if abs(xi-center)<=window]
    yw=[yi for xi,yi in zip(x,y) if abs(xi-center)<=window]
    best=None
    x0=center-3.0
    while x0<=center+3.0+1e-9:
        gamma=2.0 if kind=='lor' else 2.0
        while gamma<=30.0+1e-9:
            A,c,sse=linear_peak_fit(xw,yw,x0,gamma,kind)
            if A>0 and (best is None or sse<best[0]): best=(sse,x0,gamma,A,c)
            gamma+=0.25
        x0+=0.25
    sx=0.1; sg=0.1
    while sx>1e-6 or sg>1e-6:
        sse0,x0,gamma,A,c=best; improved=False
        for dx in (-sx,0,sx):
            for dg in (-sg,0,sg):
                nx=x0+dx; ng=gamma+dg
                if ng<=0.01: continue
                A2,c2,sse2=linear_peak_fit(xw,yw,nx,ng,kind)
                if A2>0 and sse2<sse0-1e-12:
                    best=(sse2,nx,ng,A2,c2); sse0=sse2; improved=True
        if not improved:
            sx*=0.5; sg*=0.5
    sse,x0,gamma,A,c=best
    return x0,gamma,A,c,math.sqrt(sse/len(xw)),len(xw)

for kind in ['lor','gauss']:
    print('\nMODEL',kind)
    for name,center in [('G',1580.0),('2D',2670.0)]:
        for w in [50,70,90,110,130]:
            x0,g,A,c,rmse,n=fit_peak(xs,ys,kind,center,w)
            print(f'{name:2s} w={w:3d} x0={x0:10.4f} gamma={g:9.4f} A={A:11.2f} off={c:10.2f} rmse={rmse:8.2f} n={n}')
